/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
int hobp_bus_rx(UInt32 timeout)
{
  int data = HOBP_BUS_TIMEOUT ;
  
  Hobp_Bus_Rx_Q_Msg * q_msg = (Hobp_Bus_Rx_Q_Msg *) q_remove (hobp_bus_vars.rx_q_pending , timeout);

  if(q_msg)
    {
      data = q_msg->data ;

      q_return ((Q_Msg *) q_msg);           
    }  
  return data ; 


}
